/** Stable game host that loads a replaceable manifest into a permanent runtime. */
import { manifest } from "../agent-response/manifest";
import { GameRuntime } from "../runtime/game-runtime";

/**
 * What it does: Mounts the current manifest in its matching permanent game runtime.
 * Can be generated by AI?: No.
 */
export default function PlayPage() {
  return <GameRuntime manifest={manifest} />;
}
